  const center=result.point.clone().add(new THREE.Vector3(0,this.config.arrival.anchorHeight,0)),eligible=[...star.passed].filter(u=>u.alive).map(unit=>({unit,...this.world.nearest(unit,center)})).filter(u=>{const block=this.world.solid(center,u.point,0);return u.distance<=this.config.arrival.strikeRadius&&(!block||block.t>=1-this.config.arrival.visibilityTolerance);}).sort((a,b)=>a.distance-b.distance),target=eligible[0];
